"""New v7 scenarios. Executes the exact shipped HTML; no alternate frontend.
Native file navigation was attempted separately and blocked by browser policy.
Storage durability here uses an explicit test adapter, not native file storage.
"""
import asyncio,json,os,traceback
from pathlib import Path
from playwright.async_api import async_playwright
ROOT=Path(__file__).resolve().parents[1]
results=[]
def check(name,condition,detail=None):
 assert condition,name+' '+str(detail or '')
 results.append({'name':name,'status':'passed',**({'detail':detail} if detail is not None else {})});print('[sculpt browser] PASS',name,flush=True)
async def main():
 async with async_playwright() as p:
  browser=await p.chromium.launch(executable_path=os.environ.get('CHROMIUM','/usr/bin/chromium'),headless=True,args=['--no-sandbox'])
  page=await browser.new_page(viewport={'width':1440,'height':900},reduced_motion='reduce',accept_downloads=True)
  errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
  try:
   await page.set_content((ROOT/'diagram-studio.html').read_text(),wait_until='load')
   await page.wait_for_function('window.diagramStudio?.diagnostics().ready')
   check('v7 boots in Edit with the new tools visible',await page.evaluate("diagramStudio.version==='7.0.0'&&diagramStudio.diagnostics().tool==='select'"))
   # Install a specifically identified storage adapter for assertions of stored bytes.
   await page.evaluate("window.__testStorage={};Object.defineProperty(window,'localStorage',{configurable:true,value:{getItem:k=>__testStorage[k]??null,setItem:(k,v)=>__testStorage[k]=String(v),removeItem:k=>delete __testStorage[k]}})")
   await page.evaluate("diagramStudio.loadSample('branches')")
   before=await page.evaluate('diagramStudio.get()');depth=await page.evaluate('diagramStudio.diagnostics().undoDepth')
   await page.keyboard.press('Alt+t')
   await page.wait_for_function('diagramStudio.timelineState().journey&&!diagramStudio.timelineState().journey.busy',timeout=120000)
   count=await page.evaluate('diagramStudio.timelineState().journey.frames')
   check('Alt T records more than two real solver checkpoints',count>2,{'frames':count})
   check('Opening the timeline does not alter committed geometry or history',before['layout']==await page.evaluate('diagramStudio.get().layout') and depth==await page.evaluate('diagramStudio.diagnostics().undoDepth'))
   check('Title and layout controls are disabled while geometry is only a preview',await page.evaluate("document.getElementById('document-title').disabled&&document.getElementById('algorithm-quick').disabled"))
   await page.locator('#journey-slider').focus();await page.keyboard.press('End')
   await page.wait_for_timeout(100)
   check('Native keyboard End previews the computed finish',await page.evaluate('diagramStudio.timelineState().journey.index')==count-1)
   await page.keyboard.press('Home');await page.keyboard.press('ArrowRight')
   check('Native Home and arrows scrub one recorded checkpoint at a time',await page.evaluate('diagramStudio.timelineState().journey.index')==1)
   r=await page.locator('#journey-slider').bounding_box()
   await page.mouse.move(r['x']+r['width']*.75,r['y']+r['height']/2);await page.wait_for_timeout(120)
   check('Hover peeks without changing the chosen slider stop',await page.evaluate('diagramStudio.timelineState().journey.peek!==null&&diagramStudio.timelineState().journey.index===1'))
   await page.mouse.move(r['x'],r['y']-45);await page.wait_for_timeout(100)
   check('Leaving hover restores the chosen stop',await page.evaluate('diagramStudio.timelineState().journey.peek===null&&diagramStudio.timelineState().journey.index===1'))
   check('Scrubbing never writes candidate geometry to document or storage',before['layout']==await page.evaluate('diagramStudio.get().layout') and before['layout']==await page.evaluate("JSON.parse(__testStorage['diagram-studio-v5']).layout"))
   blocked=await page.evaluate("diagramStudio.export('svg').then(()=>false,()=>true)")
   check('Diagram export cannot accidentally save an uncommitted timeline preview',blocked)
   await page.click('[data-sculpt=fit-path]');camera=await page.evaluate('diagramStudio.get().camera')
   await page.click('[data-sculpt=end]');await page.click('[data-sculpt=start]')
   check('Explicit Fit path provides one unchanged camera across slider stops',camera==await page.evaluate('diagramStudio.get().camera'))
   await page.select_option('#journey-ghost','final');await page.wait_for_timeout(150)
   check('Computed-finish ghost is drawn without modifying live data',await page.locator('.sculpt-ghost').count()>0 and before['layout']==await page.evaluate('diagramStudio.get().layout'))
   await page.select_option('#journey-ghost','off');await page.wait_for_timeout(80)
   check('Ghost can be disabled',await page.locator('.sculpt-ghost').count()==0)
   await page.select_option('#journey-ghost','next')
   await page.click('[data-sculpt=play]');await page.wait_for_timeout(850);await page.click('[data-sculpt=play]')
   check('Explicit playback advances recorded states and pauses',await page.evaluate('diagramStudio.timelineState().journey.index>0') and await page.locator('#journey-play').text_content()=='Play')
   idx=max(1,count//5);await page.evaluate('(i)=>diagramStudio.scrub(i)',idx);await page.click('[data-sculpt=bookmark]')
   check('Bookmark captures an exact restore source',await page.evaluate(f"diagramStudio.timelineState().brush.referenceLabel==='Timeline step {idx}'&&diagramStudio.timelineState().journey.bookmarks.some(b=>b.index==={idx})"))
   await page.wait_for_timeout(3600)
   await page.screenshot(path=str(ROOT/'previews'/'timeline.png'))
   for w,h in [(1024,768),(1440,900)]:
    await page.set_viewport_size({'width':w,'height':h});await page.wait_for_timeout(100)
    dims=await page.evaluate("(()=>{const e=document.getElementById('journey-deck'),r=e.getBoundingClientRect();return {fits:r.left>=0&&r.right<=innerWidth&&r.bottom<=innerHeight,overflow:e.scrollWidth>e.clientWidth+1,height:r.height}})()")
    check(f'Timeline controls fit without horizontal scrolling at {w}×{h}',dims['fits'] and not dims['overflow'],dims)
    if w==1024:await page.screenshot(path=str(ROOT/'previews'/'timeline-laptop.png'))
   await page.click('[data-sculpt=end]');await page.wait_for_timeout(150)
   final=await page.evaluate('diagramStudio.getJourney().frames.at(-1).nodes');preview_routes=await page.evaluate('diagramStudio.diagnostics().routes')
   await page.click('[data-sculpt=keep-brush]');await page.wait_for_timeout(120)
   check('Keep & brush commits exactly the shown coordinates as one undo entry',final==await page.evaluate('diagramStudio.get().layout.nodes') and depth+1==await page.evaluate('diagramStudio.diagnostics().undoDepth'))
   check('Kept route polylines match the chosen preview',preview_routes==await page.evaluate('diagramStudio.diagnostics().routes'))
   check('Timeline application never persists local holds or invocation scope in diagram settings',await page.evaluate("!('fixedIds' in diagramStudio.get().settings)&&!('selected' in diagramStudio.get().settings)&&!('scope' in diagramStudio.get().settings)&&document.getElementById('engine-status').textContent.includes('Timeline step')"))
   check('Keep & brush begins restoration from the bookmarked step',await page.evaluate("diagramStudio.diagnostics().tool==='brush'&&diagramStudio.timelineState().brush.settings.mode==='restore'"))
   check('Leaving the timeline restores disabled editor controls',await page.evaluate("!document.getElementById('document-title').disabled&&!document.getElementById('algorithm-quick').disabled"))
   await page.evaluate("document.getElementById('brush-radius').value='60';document.getElementById('brush-radius').dispatchEvent(new Event('input',{bubbles:true}))")
   await page.evaluate("document.getElementById('brush-strength').value='70';document.getElementById('brush-strength').dispatchEvent(new Event('input',{bubbles:true}))")
   # Hit a moved node away from the control dock.
   r=await page.locator('#world [data-node=n08] .node-shape').bounding_box();x=r['x']+r['width']/2;y=r['y']+r['height']/2
   await page.mouse.move(x,y);await page.wait_for_timeout(150)
   prior=await page.evaluate('diagramStudio.get()');ud=await page.evaluate('diagramStudio.diagnostics().undoDepth')
   check('Brush hover shows eligibility without mutating geometry',len(await page.evaluate('diagramStudio.timelineState().brush.eligible'))>0 and prior['layout']==await page.evaluate('diagramStudio.get().layout'))
   await page.wait_for_timeout(3600)
   await page.screenshot(path=str(ROOT/'previews'/'local-restore.png'))
   await page.mouse.down();await page.wait_for_timeout(480)
   check('Holding a stroke previews local motion without committing during the gesture',await page.evaluate('diagramStudio.timelineState().brush.stroke') and prior['layout']==await page.evaluate('diagramStudio.get().layout'))
   await page.mouse.up();await page.wait_for_timeout(150)
   after=await page.evaluate('diagramStudio.get()');held=await page.evaluate('diagramStudio.timelineState().brush.holds')
   changed=[id for id,p in prior['layout']['nodes'].items() if p!=after['layout']['nodes'][id]]
   check('A held local-restore stroke changes a subset, with exactly one undo entry',len(changed)>0 and len(changed)<len(prior['graph']['nodes']) and await page.evaluate('diagramStudio.diagnostics().undoDepth')==ud+1,{'changed':changed})
   check('Restored nodes get temporary local holds, not pins',len(held)>0 and all(prior['layout']['nodes'][id]['pinned']==after['layout']['nodes'][id]['pinned'] for id in held))
   await page.keyboard.press('Control+z')
   check('Undo restores the entire stroke and its local holds',prior['layout']==await page.evaluate('diagramStudio.get().layout') and not await page.evaluate('diagramStudio.timelineState().brush.holds'))
   await page.keyboard.press('Control+Shift+z')
   check('Redo restores both stroke geometry and local holds',after['layout']==await page.evaluate('diagramStudio.get().layout') and held==await page.evaluate('diagramStudio.timelineState().brush.holds'))
   check('Comparison generation receives the current local holds',await page.evaluate('JSON.stringify(exConfig().fixedIds.sort())===JSON.stringify(sculptFixedIds().sort())'))
   # Restore may continue through a local hold; pins remain protected.
   await page.mouse.move(x,y);await page.wait_for_timeout(100)
   check('Further restoration can reach already-held nodes',len(await page.evaluate('diagramStudio.timelineState().brush.eligible'))>0)
   before_cancel=await page.evaluate('diagramStudio.get()');d=await page.evaluate('diagramStudio.diagnostics().undoDepth')
   await page.mouse.down();await page.wait_for_timeout(250);await page.keyboard.press('Escape');await page.mouse.up();await page.wait_for_timeout(150)
   check('Escape cancels an in-flight brush stroke with no undo entry or leaked edit',before_cancel==await page.evaluate('diagramStudio.get()') and d==await page.evaluate('diagramStudio.diagnostics().undoDepth'))
   await page.keyboard.press(']');check('Bracket keys resize the active brush rather than toggling side panels',await page.evaluate('diagramStudio.timelineState().brush.settings.radius')==80)
   prior=await page.evaluate('diagramStudio.get()');await page.keyboard.down('Space');await page.mouse.move(800,150);await page.mouse.down();await page.mouse.move(830,180,steps=5);await page.mouse.up();await page.keyboard.up('Space')
   check('Space-drag in brush mode pans without altering objects',prior['layout']==await page.evaluate('diagramStudio.get().layout') and prior['camera']!=await page.evaluate('diagramStudio.get().camera'))
   await page.click('[data-sculpt=timeline-from-here]');await page.wait_for_function('diagramStudio.timelineState().journey&&!diagramStudio.timelineState().journey.busy',timeout=120000)
   frames=await page.evaluate('diagramStudio.getJourney().frames')
   check('The next global timeline protects locally restored nodes at every checkpoint',all(all(f['nodes'][id]==after['layout']['nodes'][id] for id in held) for f in frames))
   before=await page.evaluate('diagramStudio.get()');depth=await page.evaluate('diagramStudio.diagnostics().undoDepth');await page.keyboard.press('Escape')
   check('Cancel timeline preserves the working document and history',before==await page.evaluate('diagramStudio.get()') and depth==await page.evaluate('diagramStudio.diagnostics().undoDepth'))
   await page.click('#file-menu-btn');await page.click('[data-action=journey-reopen]')
   check('A finished path can be reopened without rerunning the solver',await page.evaluate('!!diagramStudio.timelineState().journey&&!diagramStudio.timelineState().journey.busy'))
   await page.keyboard.press('Escape')
   exported=await page.evaluate('JSON.stringify(diagramStudio.getJourney())')
   invalid=await page.evaluate("(async()=>{const a=diagramStudio.getJourney(),before=JSON.stringify(diagramStudio.get());a.frames[0].metrics.overlaps='not a number';try{await diagramStudio.import(JSON.stringify(a));return false;}catch{return JSON.stringify(diagramStudio.get())===before;}})()")
   check('Invalid timeline metrics are rejected before changing the working document',invalid)
   invalid_pin=await page.evaluate("(async()=>{const a=diagramStudio.getJourney(),id=a.baseline.graph.nodes[0].id,before=JSON.stringify(diagramStudio.get());a.baseline.layout.nodes[id].pinned=true;for(const f of a.frames)f.nodes[id].pinned=true;a.frames[0].nodes[id].x+=100;try{await diagramStudio.import(JSON.stringify(a));return false;}catch{return JSON.stringify(diagramStudio.get())===before;}})()")
   check('A recorded path cannot smuggle movement of a pinned object through import',invalid_pin)
   await page.evaluate('(text)=>diagramStudio.import(text)',exported)
   check('A saved timeline round-trips through import, retaining checkpoints',await page.evaluate('diagramStudio.timelineState().journey.frames')==len(frames))
   await page.keyboard.press('Escape')
   await page.keyboard.press('w');await page.select_option('#brush-mode','protect')
   await page.click('[data-sculpt=clear-holds]')
   r=await page.locator('#world [data-node=n08] .node-shape').bounding_box();x=r['x']+r['width']/2;y=r['y']+r['height']/2
   prior=await page.evaluate('diagramStudio.get()');await page.mouse.move(x,y);await page.mouse.down();await page.mouse.up()
   check('Hold brush changes protection without moving or pinning nodes',prior['layout']==await page.evaluate('diagramStudio.get().layout') and len(await page.evaluate('diagramStudio.timelineState().brush.holds'))>0)
   await page.keyboard.press('Control+z');check('Protection-only stroke is undoable',not await page.evaluate('diagramStudio.timelineState().brush.holds'))
   await page.keyboard.press('Control+Shift+z');check('Protection-only stroke is redoable',len(await page.evaluate('diagramStudio.timelineState().brush.holds'))>0)
   await page.keyboard.press('Escape');await page.keyboard.press('Escape')
   check('Repeated Escape returns to Edit after brush and timeline modes',await page.evaluate("diagramStudio.diagnostics().tool==='select'"))
   svg=await page.evaluate("diagramStudio.export('svg')")
   check('SVG export contains committed graph metadata but no brush UI or local-hold adornments','diagram-studio-data' in svg and 'sculpt-held' not in svg and 'brush-outer' not in svg)
   png=await page.evaluate("diagramStudio.export('png').then(b=>({type:b.type,size:b.size}))")
   check('PNG export still produces an actual PNG blob',png['type']=='image/png' and png['size']>1000,png)
   await page.evaluate("diagramStudio.loadSample('process')")
   check('Changing documents clears local holds and stale restore sources',not await page.evaluate('diagramStudio.timelineState().brush.holds') and not await page.evaluate('diagramStudio.timelineState().brush.hasReference'))
   # Cancellation during compute: do not await the public async function.
   await page.evaluate("void diagramStudio.timeline({algorithm:'stress',maxIterations:1200})");await page.keyboard.press('Escape');await page.wait_for_timeout(250)
   check('Escape cancels an in-progress timeline worker without late adoption',await page.evaluate('diagramStudio.timelineState().journey===null'))
   # A simulated source change invalidates the candidate, rather than losing an edit.
   await page.evaluate('diagramStudio.timeline({maxIterations:80})');await page.evaluate("D.graph.nodes[0].title='An external edit';diagramStudio.keepFrame()")
   check('Stale candidate guard preserves a concurrent semantic edit',await page.evaluate("diagramStudio.get().graph.nodes[0].title==='An external edit'&&diagramStudio.timelineState().journey===null"))
   # Disable Worker deliberately: the local solver remains available.
   await page.evaluate("()=>{window.__realWorker=window.Worker;window.Worker=class {constructor(){throw Error('Test-only worker denial');}};}")
   await page.evaluate('diagramStudio.timeline({maxIterations:80})')
   check('Worker denial falls back to a usable local timeline',await page.evaluate('!!diagramStudio.timelineState().journey&&!diagramStudio.timelineState().journey.busy&&diagramStudio.timelineState().journey.frames>0'))
   await page.keyboard.press('Escape');await page.evaluate('()=>{window.Worker=window.__realWorker;}')
   # Exact HTML + adapter restoration simulates boot; not file-origin storage.
   await page.wait_for_timeout(250);saved=await page.evaluate('JSON.stringify(__testStorage)')
   other=await browser.new_page(viewport={'width':1440,'height':900});await other.evaluate('(raw)=>{window.__saved=JSON.parse(raw);Object.defineProperty(window,"localStorage",{configurable:true,value:{getItem:k=>__saved[k]??null,setItem:(k,v)=>__saved[k]=v,removeItem:k=>delete __saved[k]}})}',saved)
   await other.set_content((ROOT/'diagram-studio.html').read_text());await other.wait_for_function('window.diagramStudio?.diagnostics().ready')
   check('Committed geometry restores on a fresh boot with the explicit storage adapter',await other.evaluate('diagramStudio.get().layout.nodes')==json.loads(json.loads(saved)['diagram-studio-v5'])['layout']['nodes'])
   await other.close()
   check('No uncaught browser errors in new timeline and brush scenarios',not errors,errors)
   (ROOT/'verification'/'sculpt-browser-results.json').write_text(json.dumps({'passed':len(results),'browserErrors':errors,'navigation':'HTML injected after separately verified native file policy block','storage':'explicit test adapter, not native file-origin persistence','results':results},indent=2))
  except Exception:
   await page.screenshot(path=str(ROOT/'verification'/'sculpt-failure.png'))
   print('FAIL',traceback.format_exc(),flush=True);print('ERRORS',errors,flush=True);raise
  finally:await browser.close()
asyncio.run(main())
